'use strict';
const test=require('node:test');const assert=require('node:assert/strict');const H=require('./secureshopMailAgentReadRenderedQualification');
const ids=['11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333'];
const ref={version:1,shopUserId:7,sessionId:ids[0],requestId:ids[1],startedAt:9};
test('closed V11 DTO requires saved replay',()=>{assert.throws(()=>H.dto({completed:true,replayed:false,judgment:{verdict:'pass',evaluationId:ids[2],canRetry:false}},{saved:true}));assert.equal(H.dto({completed:false,status:'unavailable',modelEvaluated:false,reason:'evidence_size_limit'}).status,'unavailable');});
test('reference is exact IDs-only',()=>{assert.deepEqual(H.reference(ref),ref);assert.throws(()=>H.reference({...ref,body:'private'}));});
test('receipt binds observed actor and one-criterion Judge bounds',()=>{const value=Object.fromEntries(H.V11_FLAGS.map(k=>[k,true]));Object.assign(value,{scope:H.V11_SCOPE,actorCalls:12,deniedHopCount:1,judgeCalls:2,roleTurns:6,assessmentPosts:2,savedAssessmentGets:1,genuineCredit:1,errors:[]});assert.equal(H.assertReceipt(value),value);assert.equal(H.assertReceipt({...value,fixtureLocalCandidateAdmission:false}).fixtureLocalCandidateAdmission,false);assert.throws(()=>H.assertReceipt({...value,fixtureLocalCandidateAdmission:'false'}));assert.equal(H.assertReceipt({...value,actorCalls:13,deniedHopCount:2,judgeCalls:1}).actorCalls,13);assert.throws(()=>H.assertReceipt({...value,actorCalls:13}));assert.throws(()=>H.assertReceipt({...value,actorCalls:13,deniedHopCount:2}));assert.throws(()=>H.assertReceipt({...value,deniedHopCount:0}));assert.throws(()=>H.assertReceipt({...value,deniedHopCount:3}));assert.throws(()=>H.assertReceipt({...value,judgeCalls:0}));});
test('runner rejects empty fixed/reset/sibling claims',async()=>{const detail={body:{sessionId:ids[0],requestId:ids[1]},receipt:{mailRead:{result:{kind:'detail',message:{bodyMarkdown:'foreign body'}}}}};await assert.rejects(H.runV11Qualification({detail,actions:{visibleBody:async()=>true,assess:async()=>({value:{completed:true,replayed:false,judgment:{verdict:'pass',evaluationId:ids[2],canRetry:false}}}),armReload:()=>true,reload:async()=>{},finishReload:async()=>({value:{completed:true,replayed:true,judgment:{verdict:'pass',evaluationId:ids[2],canRetry:false}}})},observe:{original:async()=>({sessionId:ids[0],requestId:ids[1],body:'foreign body'}),ready:async()=>ref,canonical:async()=>({retainedPacket:true,durableProgress:true}),finalize:async()=>({})},guards:{fixed:async()=>({}),sibling:async()=>({}),reset:async()=>({})}}));});
test('reload observation arms before the caller reload and finishes its one automatic GET',async()=>{let resolveRequest,resolveResponse,listener=null,removed=false;const requestFrame={},path=`/api/secureshop/agents/merchant/assistant/mail-read/assessment/${ref.sessionId}/${ref.requestId}`;const request={url:()=>`http://shop.test${path}`,method:()=> 'GET',frame:()=>requestFrame};const response={request:()=>request,ok:()=>true,headers:()=>({'content-type':'application/json'}),json:async()=>({completed:true,replayed:true,judgment:{verdict:'pass',evaluationId:ids[2],canRetry:false}})};const page={on:(_name,fn)=>{listener=fn;},off:(_name,fn)=>{assert.equal(fn,listener);removed=true;},waitForRequest:()=>new Promise(resolve=>{resolveRequest=resolve;}),waitForResponse:()=>new Promise(resolve=>{resolveResponse=resolve;})};const actions=H.createV11AssessmentActions({page,frame:{},requestFrame,origin:'http://shop.test',readAssessmentReference:async()=>ref,timeout:1000});assert.equal(actions.armReload(ref),true);listener(request);resolveRequest(request);resolveResponse(response);const value=await actions.finishReload(ref);assert.equal(value.value.replayed,true);assert.equal(removed,true);});
test('real Puppeteer non-ok method rejects even with a valid JSON body',async()=>{let rq,rs,listener;const requestFrame={},path=`/api/secureshop/agents/merchant/assistant/mail-read/assessment/${ref.sessionId}/${ref.requestId}`,request={url:()=>`http://shop.test${path}`,method:()=> 'GET',frame:()=>requestFrame},response={request:()=>request,ok:()=>false,headers:()=>({'content-type':'application/json'}),json:async()=>({completed:false,status:'unconfirmed',modelEvaluated:false})},page={on:(_n,fn)=>{listener=fn;},off:()=>{},waitForRequest:()=>new Promise(resolve=>{rq=resolve;}),waitForResponse:()=>new Promise(resolve=>{rs=resolve;})},actions=H.createV11AssessmentActions({page,frame:{},requestFrame,origin:'http://shop.test',readAssessmentReference:async()=>ref,timeout:1000});actions.armReload(ref);listener(request);rq(request);rs(response);await assert.rejects(actions.finishReload(ref));});

test('async Puppeteer frame supplier scrolls the exact offscreen button before its physical hit test',async()=>{
 let requestResolve,responseResolve,listener,clicks=0,activeCalls=0,waits=0,disposed=0,scrolled=false;
 const requestFrame={},path='/api/secureshop/agents/merchant/assistant/mail-read/assess';
 const request={url:()=>`http://shop.test${path}`,method:()=> 'POST',frame:()=>requestFrame,postData:()=>JSON.stringify({sessionId:ref.sessionId,requestId:ref.requestId})};
 const response={request:()=>request,ok:()=>true,headers:()=>({'content-type':'application/json'}),json:async()=>({completed:true,replayed:false,judgment:{verdict:'pass',evaluationId:ids[2],canRetry:false}})};
 const page={on:(_name,fn)=>{listener=fn;},off:(_name,fn)=>assert.equal(fn,listener),waitForRequest:()=>new Promise(resolve=>{requestResolve=resolve;}),waitForResponse:()=>new Promise(resolve=>{responseResolve=resolve;})};
 const domButton={textContent:'Assess agent-selected mail',disabled:false,isConnected:true,getClientRects:()=>[{}],getBoundingClientRect:()=>({left:0,top:scrolled?0:2000,width:100,height:30}),contains:()=>false,scrollIntoView:()=>{scrolled=true;}};
 const element={evaluate:async fn=>fn(domButton),click:async()=>{assert.equal(scrolled,true);clicks++;listener(request);requestResolve(request);responseResolve(response);}};
 const attached={asElement:()=>element,dispose:async()=>{disposed++;}},hitReady={dispose:async()=>{disposed++;}};
 const priorDocument=global.document;
 global.document={querySelectorAll:()=>[domButton],elementFromPoint:()=>scrolled?domButton:null};
 const puppeteerFrame={
  waitForFunction:async(predicate,_options,...args)=>{waits++;const value=predicate(...args.map(value=>value===element?domButton:value));if(waits===1){assert.equal(value,false);return{dispose:async()=>{disposed++;}};}if(waits===2){assert.equal(value,domButton);assert.equal(scrolled,false);return attached;}assert.equal(value,true);assert.equal(scrolled,true);return hitReady;}
 };
 let referenceReads=0;const actions=H.createV11AssessmentActions({page,frame:async()=>{activeCalls++;await Promise.resolve();return puppeteerFrame;},requestFrame,origin:'http://shop.test',readAssessmentReference:async()=>referenceReads++===0?null:ref,timeout:1000});
 try{
  assert.equal(await actions.visibleBody('foreign body'),true);
  const wire=await actions.assess({shopUserId:ref.shopUserId,sessionId:ref.sessionId,requestId:ref.requestId});
  assert.equal(wire.value.completed,true);
  assert.equal(clicks,1);
  assert.equal(activeCalls,2);
  assert.equal(waits,3);
  assert.equal(disposed,2);assert.deepEqual(wire.snapshot,ref);assert.equal(referenceReads,2);
 }finally{global.document=priorDocument;}
});
